// ===== Settings: edit these =====
const CONFIG = {
  model: 'claude-opus-5-5',        // Claude model for all three passes
  draft_effort: 'high',            // low | medium | high | xhigh | max
  audit_effort: 'medium',
  final_effort: 'high',
  max_tokens: 32000,               // per call; includes thinking tokens
  max_final_attempts: 3,           // final pass reruns when the integrity check fails
  create_google_doc_default: true, // can be overridden per request with create_google_doc
  google_folder_id: '',            // Drive folder for new Docs; blank = My Drive root
  min_length_ratio: 0.5,           // flag rewrites shorter than 50% of the original
  max_content_chars: 150000,
};
// =================================

const body = $json.body || {};
const errors = [];
const str = (v) => (typeof v === 'string' ? v.trim() : '');
const bool = (v, d) => (v === undefined || v === null || v === '' ? d : v === true || v === 'true' || v === 1 || v === '1');
const toList = (v) => Array.isArray(v)
  ? v.map((x) => String(x).trim()).filter(Boolean)
  : typeof v === 'string' ? v.split(',').map((s) => s.trim()).filter(Boolean) : [];

const content = typeof body.content === 'string' ? body.content.replace(/\r\n/g, '\n').trim() : '';
if (!content) errors.push('`content` is required and must be a non-empty string.');
if (content.length > CONFIG.max_content_chars) errors.push(`\`content\` is ${content.length} characters; the limit is ${CONFIG.max_content_chars}.`);

const detectFormat = (t) => {
  if (/<\/?(p|h[1-6]|div|ul|ol|li|a|br|strong|em|blockquote|section|article)\b[^>]*>/i.test(t)) return 'html';
  if (/^#{1,6}\s+\S/m.test(t) || /\[[^\]]+\]\([^)\s]+\)/.test(t) || /^\s*(?:[-*+]|\d+\.)\s+\S/m.test(t) || /\*\*[^*\n]+\*\*/.test(t)) return 'markdown';
  return 'text';
};
let format = str(body.format).toLowerCase() || 'auto';
if (format === 'md') format = 'markdown';
if (format === 'auto') format = detectFormat(content);
if (!['html', 'markdown', 'text'].includes(format)) errors.push('`format` must be html, markdown, text, or auto.');

const contentType = str(body.content_type).toLowerCase() || 'auto';
if (!['auto', 'marketing', 'reference'].includes(contentType)) errors.push('`content_type` must be auto, marketing, or reference.');

const callbackUrl = str(body.callback_url);
if (callbackUrl && !/^https?:\/\//i.test(callbackUrl)) errors.push('`callback_url` must start with http:// or https://.');

return [{ json: {
  valid: errors.length === 0,
  errors,
  config: CONFIG,
  title: str(body.title) || 'Untitled blog post',
  content,
  format,
  content_type: contentType,
  target_keyword: str(body.target_keyword),
  secondary_keywords: toList(body.secondary_keywords),
  voice_sample: str(body.voice_sample),
  notes: str(body.notes),
  create_google_doc: bool(body.create_google_doc, CONFIG.create_google_doc_default),
  google_folder_id: str(body.google_folder_id) || CONFIG.google_folder_id,
  include_draft: bool(body.include_draft, false),
  callback_url: callbackUrl,
  async: Boolean(callbackUrl),
  received_at: new Date().toISOString(),
} }];

// Swaps content the rewrite must not touch for [[KEEP_n]] tokens, and records
// the post's SEO structure so the Integrity Check can compare against it.
const input = $('Validate Input').first().json;
const TOKEN_RE = /\[\[KEEP_(\d+)\]\]/g;
const stripTags = (s) => s.replace(/<[^>]+>/g, ' ');
const decode = (s) => s.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&(rsquo|lsquo|#8217|#8216);/g, "'").replace(/&(rdquo|ldquo|#8220|#8221);/g, '"').replace(/&(mdash|#8212);/g, '—').replace(/&(ndash|#8211);/g, '–');
const plain = (s, format) => {
  let t = s.replace(TOKEN_RE, ' ');
  if (format === 'html') t = decode(stripTags(t));
  if (format === 'markdown') t = t.replace(/\]\([^)]*\)/g, ']').replace(/[#*_>\[\]]/g, ' ');
  return t.replace(/\s+/g, ' ').trim();
};
const words = (s) => (s ? s.split(/\s+/).filter(Boolean) : []);
const headingsOf = (s, format) => {
  const out = []; let m;
  if (format === 'html') {
    const re = /<h([1-6])\b[^>]*>([\s\S]*?)<\/h\1>/gi;
    while ((m = re.exec(s))) out.push({ level: +m[1], text: decode(stripTags(m[2])).replace(/\s+/g, ' ').trim() });
  } else if (format === 'markdown') {
    const re = /^(#{1,6})\s+(.+?)\s*#*\s*$/gm;
    while ((m = re.exec(s))) out.push({ level: m[1].length, text: m[2].trim() });
  }
  return out;
};
const linksOf = (s, format) => {
  const out = []; let m;
  const a = /<a\b[^>]*?\bhref\s*=\s*["']([^"']+)["']/gi;
  while ((m = a.exec(s))) out.push(m[1]);
  if (format !== 'html') {
    const md = /(?<!!)\[[^\]]*\]\(\s*<?([^)\s>]+)>?(?:\s+"[^"]*")?\s*\)/g;
    while ((m = md.exec(s))) out.push(m[1]);
  }
  if (format === 'text') {
    const bare = /https?:\/\/[^\s<>"')\]]+/g;
    while ((m = bare.exec(s))) out.push(m[0].replace(/[.,;:!?]+$/, ''));
  }
  return [...new Set(out)];
};
const escRe = (k) => k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const countOf = (t, kw) => (kw ? (t.match(new RegExp(escRe(kw), 'gi')) || []).length : 0);
const keywordProfile = (s, format, kw) => {
  const p = plain(s, format);
  return {
    total: countOf(p, kw),
    in_first_100_words: countOf(words(p).slice(0, 100).join(' '), kw) > 0,
    in_heading: headingsOf(s, format).some((h) => h.level >= 2 && countOf(h.text, kw) > 0),
  };
};
const dashCount = (s, format) => {
  const t = format === 'html' ? decode(stripTags(s.replace(TOKEN_RE, ' '))) : s.replace(TOKEN_RE, ' ');
  return (t.match(/[—–]/g) || []).length;
};

const blocks = [];
let text = input.content;
const protect = (re) => { text = text.replace(re, (m) => { blocks.push(m); return `[[KEEP_${blocks.length}]]`; }); };

protect(/^---\n[\s\S]*?\n---\n/);                    // YAML frontmatter
protect(/```[\s\S]*?```/g);                           // fenced code
protect(/~~~[\s\S]*?~~~/g);
protect(/<!--[\s\S]*?-->/g);                          // HTML / Gutenberg block comments
protect(/<(pre|script|style|iframe|svg|video|audio|table|figure)\b[\s\S]*?<\/\1>/gi);
protect(/<img\b[^>]*>/gi);                            // images keep src + alt
protect(/<code\b[^>]*>[\s\S]*?<\/code>/gi);
protect(/!\[[^\]]*\]\([^)]*\)/g);                     // markdown images
protect(/`[^`\n]+`/g);                                // inline code
protect(/\[(?:embed|video|audio|caption|gallery)[^\]]*\][\s\S]*?\[\/(?:embed|video|audio|caption|gallery)\]/gi); // WP shortcodes

const preview = (s) => { const one = s.replace(/\s+/g, ' ').trim(); return one.length > 160 ? one.slice(0, 160) + '...' : one; };
const legend = blocks.map((b, i) => `[[KEEP_${i + 1}]] = ${preview(b)}`);

const kw = input.target_keyword;
const profile = {
  headings: headingsOf(text, input.format),
  links: linksOf(text, input.format),
  words: words(plain(text, input.format)).length,
  keyword: keywordProfile(text, input.format, kw),
  dashes: dashCount(text, input.format),
};

const contentTypeLine = input.content_type === 'auto'
  ? 'auto (detect it; an incoming blog post is usually marketing mode)'
  : input.content_type;

const context = [
  '<post_metadata>',
  `Title: ${input.title}`,
  `Format: ${input.format}`,
  `Content type: ${contentTypeLine}`,
  `Primary keyword: ${kw || '(none given)'}`,
  `Secondary keywords: ${input.secondary_keywords.join(', ') || '(none given)'}`,
  input.notes ? `Editor notes: ${input.notes}` : null,
  '</post_metadata>',
  input.voice_sample ? `\n<voice_sample>\n${input.voice_sample}\n</voice_sample>` : null,
  legend.length ? `\n<protected_items>\nFor context only. Keep each token in place; never write out what it holds.\n${legend.join('\n')}\n</protected_items>` : null,
  `\n<original_post>\n${text}\n</original_post>`,
].filter((x) => x !== null).join('\n');

return [{ json: { tokenized: text, blocks, profile, context } }];

const input = $('Validate Input').first().json;
const prot = $('Protect Structure').first().json;
const skill = $('Humanizer Skill').first().json;
const cfg = input.config;
const buildRequest = (effort, userText, format) => ({
