const ask = `STEP 1 OF 3: DRAFT

${prot.context}

Identify the AI writing patterns in the original post, then write the draft rewrite (Process steps 1 and 2). Return only the rewritten post body inside <rewrite></rewrite> tags.`;

return [{ json: { request: buildRequest(cfg.draft_effort, ask) } }];

const readClaude = (res, step) => {
  if (res.type === 'error' || res.error) throw new Error(`Claude ${step} call failed: ${JSON.stringify(res.error || res).slice(0, 500)}`);
  if (res.stop_reason === 'refusal') throw new Error(`Claude declined the ${step} step (${res.stop_details?.category || 'no category'}).`);
  if (res.stop_reason === 'max_tokens') throw new Error(`The ${step} step hit max_tokens. Raise max_tokens in Validate Input or send a shorter post.`);
  return (res.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
};
const extractRewrite = (raw) => {
