const ask = `STEP 2 OF 3: AUDIT

${prot.context}

<draft_rewrite>
${draft}
</draft_rewrite>

Run Process step 3 on the draft rewrite. Be brief and specific:
- content_type: the mode you applied, marketing or reference.
- still_ai: what still makes the draft read as AI generated. One short item per tell, naming the pattern (for example "§9") and quoting the phrase.
- fabrications: every fact, name, number, date, quote, or citation in the draft that is not in the original post. Empty if none.
- seo_issues: in marketing mode, anything the draft broke from the SEO preservation constraints (keyword placement, headings, links, images, CTA). Also any [[KEEP_n]] token that was moved, changed, or lost. Empty if none.`;

const schema = {
  type: 'json_schema',
