  system: [{ type: 'text', text: skill.system_prompt, cache_control: { type: 'ephemeral' } }],
  messages: [{ role: 'user', content: userText }],
});
// Input comes from Read Audit on the first pass, or from Integrity Check on a retry.
const state = $json;
const isRetry = state.retry === true;
const attempt = isRetry ? state.attempt + 1 : 1;
const dashesAllowed = /[—–]/.test(input.voice_sample);
const list = (items) => (items.length ? items.map((x) => `- ${x}`).join('\n') : '- none');

let ask = `STEP 3 OF 3: FINAL

${prot.context}

<draft_rewrite>
${state.draft_tokenized}
</draft_rewrite>

<audit>
Content type applied: ${state.audit.content_type || 'unknown'}
Still reads as AI:
${list(state.audit.still_ai)}
Facts not in the original (remove or restore to the original wording):
${list(state.audit.fabrications)}
SEO and structure problems:
${list(state.audit.seo_issues)}
</audit>`;

if (isRetry) {
