<previous_final>
${state.final_tokenized}
</previous_final>

<integrity_problems>
The pipeline's automated check rejected your previous final rewrite (shown above). Fix every one of these and change nothing else that was working:
${list(state.issues)}
</integrity_problems>`;
}

