  const t = format === 'html' ? decode(stripTags(s.replace(TOKEN_RE, ' '))) : s.replace(TOKEN_RE, ' ');
  return (t.match(/[—–]/g) || []).length;
};

let finalTok = extractRewrite(readClaude($json, 'final'));
const attempt = req.attempt;
const lastAttempt = attempt >= cfg.max_final_attempts;
const dashesAllowed = /[—–]/.test(input.voice_sample);
const fixes = [];

// On the last attempt, replace leftover dashes mechanically instead of failing.
let dashes = dashCount(finalTok, format);
if (!dashesAllowed && dashes > 0 && lastAttempt) {
  finalTok = finalTok.split(/(<[^>]+>|\[\[KEEP_\d+\]\])/).map((seg, i) => (i % 2 === 1 ? seg : seg
    .replace(/(\d)\s*[–—]\s*(\d)/g, '$1-$2')
    .replace(/\s*[—–]\s*/g, ', ')
    .replace(/,\s*([.,;:!?])/g, '$1'))).join('');
  fixes.push(`Replaced ${dashes} em/en dash(es) with commas or hyphens after ${attempt} attempts.`);
  dashes = dashCount(finalTok, format);
}

const issues = [];
if (!finalTok.trim()) issues.push('The final rewrite was empty.');

// Protected tokens: each exactly once, none invented.
const counts = {};
(finalTok.match(TOKEN_RE) || []).forEach((t) => { counts[t] = (counts[t] || 0) + 1; });
for (let i = 1; i <= prot.blocks.length; i++) {
  const t = `[[KEEP_${i}]]`;
  if (!counts[t]) issues.push(`Protected token ${t} is missing. Put it back where it was in the original.`);
  else if (counts[t] > 1) issues.push(`Protected token ${t} appears ${counts[t]} times. Keep exactly one.`);
}
Object.keys(counts).forEach((t) => {
  const n = +t.match(/\d+/)[0];
  if (n < 1 || n > prot.blocks.length) issues.push(`${t} is not a real protected token. Remove it.`);
});

// Headings: same levels, same order.
if (format !== 'text') {
  const oh = prot.profile.headings;
  const fh = headingsOf(finalTok, format);
  const ol = oh.map((h) => `H${h.level}`).join(', ');
  const fl = fh.map((h) => `H${h.level}`).join(', ');
  if (ol !== fl) {
    issues.push(`Heading structure changed. The original has ${oh.length} headings in this order: ${ol || 'none'}. The rewrite has ${fh.length}: ${fl || 'none'}. Keep every heading at its level and in order. Original headings: ${oh.map((h) => `H${h.level} "${h.text}"`).join('; ')}`);
  }
}

// Links: every original target still present.
const finalLinks = new Set(linksOf(finalTok, format));
const missingLinks = prot.profile.links.filter((l) => !finalLinks.has(l));
if (missingLinks.length) issues.push(`These links were dropped: ${missingLinks.join(', ')}. Carry each one onto relevant anchor text.`);

// Primary keyword placements the original had.
const fk = keywordProfile(finalTok, format, kw);
if (kw) {
  const ok = prot.profile.keyword;
  if (ok.total > 0 && fk.total === 0) issues.push(`The primary keyword "${kw}" no longer appears. Keep it, worded exactly.`);
  else {
    if (ok.in_first_100_words && !fk.in_first_100_words) issues.push(`The primary keyword "${kw}" was in the first 100 words of the original and must stay there.`);
    if (ok.in_heading && !fk.in_heading) issues.push(`The primary keyword "${kw}" was in a subheading of the original and must stay in at least one.`);
  }
}

// Length: catch gutted sections.
const finalWords = words(plain(finalTok, format)).length;
const ratio = prot.profile.words ? finalWords / prot.profile.words : 1;
if (ratio < cfg.min_length_ratio) issues.push(`The rewrite is ${Math.round(ratio * 100)}% of the original length (${finalWords} vs ${prot.profile.words} words). Compress fluff, but keep the substance of every section.`);

// Dashes.
if (!dashesAllowed && dashes > 0) issues.push(`The rewrite still contains ${dashes} em or en dash(es). Replace every one (§14).`);

const passed = issues.length === 0;
const restore = (s) => s.replace(TOKEN_RE, (m, n) => prot.blocks[n - 1] ?? m);

return [{ json: {
  retry: !passed && !lastAttempt,
  passed,
  attempt,
  issues,
  fixes,
  final_tokenized: finalTok,
  final: restore(finalTok),
  stats: {
    words_original: prot.profile.words,
    words_final: finalWords,
    length_ratio: Math.round(ratio * 100) / 100,
    headings: prot.profile.headings.length,
    links: prot.profile.links.length,
    protected_items: prot.blocks.length,
    dashes_original: prot.profile.dashes,
    dashes_final: dashes,
    keyword_mentions_original: prot.profile.keyword.total,
    keyword_mentions_final: fk.total,
  },
  audit: req.audit,
  draft_tokenized: req.draft_tokenized,
  usage_log: [...req.usage_log, usageOf($json, `final_${attempt}`)],
} }];

const input = $('Validate Input').first().json;
const prot = $('Protect Structure').first().json;
const skill = $('Humanizer Skill').first().json;
const s = $json;

const fields = ['input_tokens', 'output_tokens', 'cache_creation_input_tokens', 'cache_read_input_tokens'];
const totals = Object.fromEntries(fields.map((f) => [f, s.usage_log.reduce((n, u) => n + (u[f] || 0), 0)]));

const result = {
  status: s.passed ? 'ok' : 'needs_review',
  title: input.title,
  format: input.format,
  content_type: s.audit.content_type || input.content_type,
  humanized_content: s.final,
  integrity: {
    passed: s.passed,
    issues: s.issues,
    fixes_applied: s.fixes,
    final_attempts: s.attempt,
  },
  draft_audit: {
    still_ai: s.audit.still_ai,
    fabrications: s.audit.fabrications,
    seo_issues: s.audit.seo_issues,
  },
  stats: s.stats,
  google_doc: null,
  model: input.config.model,
  skill_version: skill.skill_version,
  usage: { calls: s.usage_log.length, ...totals, by_step: s.usage_log },
  execution_id: $execution.id,
  completed_at: new Date().toISOString(),
};
if (input.include_draft) {
  result.draft = s.draft_tokenized.replace(/\[\[KEEP_(\d+)\]\]/g, (m, n) => prot.blocks[n - 1] ?? m);
}

return [{ json: result }];

// Builds a Drive multipart upload that converts the rewrite into a Google Doc.
// Drive imports HTML and Markdown with headings, lists, and links intact.
const input = $('Validate Input').first().json;
const r = $json;
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const c = r.humanized_content;
let mime, body;
if (r.format === 'html') {
  mime = 'text/html';
  body = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${esc(r.title)}</title></head><body>${/<h1\b/i.test(c) ? '' : `<h1>${esc(r.title)}</h1>`}${c}</body></html>`;
} else if (r.format === 'markdown') {
  mime = 'text/markdown';
  body = (/^#\s/m.test(c) ? '' : `# ${r.title}\n\n`) + c;
} else {
  mime = 'text/plain';
  body = `${r.title}\n\n${c}`;
}

const metadata = {
  name: `${r.title} (humanized)`,
  mimeType: 'application/vnd.google-apps.document',
  ...(input.google_folder_id ? { parents: [input.google_folder_id] } : {}),
};
const boundary = `humanizer_${Date.now()}`;
const multipart = [
  `--${boundary}`,
  'Content-Type: application/json; charset=UTF-8',
  '',
  JSON.stringify(metadata),
  `--${boundary}`,
  `Content-Type: ${mime}; charset=UTF-8`,
  '',
  body,
  `--${boundary}--`,
  '',
].join('\r\n');

return [{ json: { boundary, multipart } }];

const result = { ...$('Build Result').first().json };
const d = $json;
result.google_doc = d.id
  ? { id: d.id, name: d.name, url: d.webViewLink || `https://docs.google.com/document/d/${d.id}/edit` }
  : { error: (d.error && (d.error.message || JSON.stringify(d.error))) || 'Google Doc was not created.' };
return [{ json: result }];
